#!/usr/bin/env python3
"""The Gen 5-8 moves (468-754: Hone Claws .. Eerie Spell) for the Gen 5-8 fork, as generated files the stock
tables include, from tools/moemon_gen58/moves.json (expansion_moves.py).

    python3 tools/moemon_gen58/gen_moves.py

Names: Kai's capitals, 12 letters at most like Gen 3's (spaces dropped as in THUNDERPUNCH, then NAMES below).
Effects: a move that works like one Kai has uses Kai's effect (Scald = EFFECT_BURN_HIT 30%, Snarl =
EFFECT_SPECIAL_ATTACK_DOWN_HIT, Coil-like stat moves...); the others get their own EFFECT_* from 267 (after
Gen 4's), whose battle scripts are in data/battle_scripts_gen58.inc (a placeholder plays a plain hit or fails until
the effect is written). Animations: data/battle_anim_scripts_gen58.inc; a move without its own borrows a Gen 3 one
of its type (tools/moemon_gen4/gen_anims.py ports expansion's where it can).

Generated: the "Gen 5-8" blocks of include/constants/moves.h (and MOVES_COUNT) and battle_move_effects.h (and
NUM_BATTLE_MOVE_EFFECTS), src/data/battle_moves_gen58.h, src/data/text/move_names_gen58.h,
src/data/text/move_descriptions_gen58.h, src/data/contest_moves_gen58.h, src/data/move_categories_gen58.h,
src/data/move_flags_gen58.h (punching, biting, sound... for the battle code), data/battle_anim_ptrs_gen58.inc,
data/battle_effect_ptrs_gen58.inc.
"""
import json
import os
import re
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
REPO = os.path.abspath(os.path.join(HERE, '..', '..'))
sys.path.insert(0, os.path.join(REPO, 'tools', 'moemon_gen4'))
from kaitext import kai_text  # noqa: E402

GEN = '// Generated by tools/moemon_gen58/gen_moves.py. Do not edit.\n'
FIRST_NEW_EFFECT = 267

# names still over 12 letters with the spaces dropped
NAMES = {
    'TRICK-OR-TREAT': 'TRICKORTREAT', 'PARABOLIC CHARGE': 'PARABOLICCHG', 'PETAL BLIZZARD': 'PETALBLIZZRD',
    'DISARMING VOICE': 'DISARM VOICE', 'GRASSY TERRAIN': 'GRASSTERRAIN', 'STEAM ERUPTION': 'STEAM ERUPT',
    'HYPERSPACE HOLE': 'HYPERSPCHOLE', 'WATER SHURIKEN': 'WATERSHURIKN', 'ELECTRIC TERRAIN': 'ELEC TERRAIN',
    'DAZZLING GLEAM': 'DAZZLE GLEAM', 'BABY-DOLL EYES': 'BABYDOLLEYES', 'POWER-UP PUNCH': 'POWERUPPUNCH',
    'THOUSAND ARROWS': 'THOU. ARROWS', 'THOUSAND WAVES': 'THOU. WAVES', 'PRECIPICE BLADES': 'PRECIP.BLADE',
    'HYPERSPACE FURY': 'HYPERSPCFURY', 'FIRST IMPRESSION': 'FIRST IMPRSN', 'BANEFUL BUNKER': 'BANEFULBUNKR',
    'SPIRIT SHACKLE': 'SPIRITSHACKL', 'DARKEST LARIAT': 'DARK LARIAT', 'SPARKLING ARIA': 'SPARKLE ARIA',
    'FLORAL HEALING': 'FLORAL HEAL', 'HIGH HORSEPOWER': 'HIGHHORSEPWR', 'PSYCHIC TERRAIN': 'PSYCHTERRAIN',
    'REVELATION DANCE': 'REVEL. DANCE', 'CLANGING SCALES': 'CLANG SCALES', 'STOMPING TANTRUM': 'STOMPTANTRUM',
    'PRISMATIC LASER': 'PRISM LASER', 'SPECTRAL THIEF': 'SPECTRLTHIEF', 'SUNSTEEL STRIKE': 'SUNSTEELSTRK',
    'MOONGEIST BEAM': 'M.GEIST BEAM', "NATURE'S MADNESS": 'NATURMADNESS', 'SPLISHY SPLASH': 'SPLISHYSPLSH',
    'DOUBLE IRON BASH': 'DBLIRON BASH', 'DYNAMAX CANNON': 'DYNAMXCANNON', 'CLANGOROUS SOUL': 'CLANGOR SOUL',
    'BEHEMOTH BLADE': 'BEHEMTHBLADE', 'BREAKING SWIPE': 'BREAK SWIPE', 'FALSE SURRENDER': 'FALSESURRNDR',
    'METEOR ASSAULT': 'METEOR ASSLT', 'EXPANDING FORCE': 'EXPAND FORCE', 'MISTY EXPLOSION': 'MISTYEXPLODE',
    'RISING VOLTAGE': 'RISE VOLTAGE', 'BURNING JEALOUSY': 'BURNJEALOUSY', 'SCORCHING SANDS': 'SCORCH SANDS',
    'JUNGLE HEALING': 'JUNGLE HEAL', 'SURGING STRIKES': 'SURGESTRIKES', 'FREEZING GLARE': 'FREEZE GLARE',
    'THUNDEROUS KICK': 'THUNDER KICK', 'ASTRAL BARRAGE': 'ASTRLBARRAGE',
    # Gen 9
    'PSYSHIELD BASH': 'PSYSHLD BASH', 'SPRINGTIDE STORM': 'SPRINGTIDE', 'MYSTICAL POWER': 'MYSTIC POWER',
    'INFERNAL PARADE': 'INFERNPARADE', 'CEASELESS EDGE': 'CEASELESEDGE', 'BLEAKWIND STORM': 'BLEAKWIND',
    'WILDBOLT STORM': 'WILDBOLT', 'SANDSEAR STORM': 'SANDSEAR', 'LUNAR BLESSING': 'LUNARBLESSNG',
    'POPULATION BOMB': 'POPULATN BOMB'[:12], 'REVIVAL BLESSING': 'REVIVAL BLSS', 'COLLISION COURSE': 'COLLISION CRS'[:12],
    'CHILLY RECEPTION': 'CHILLY RECEP', 'CHILLING WATER': 'CHILL WATER', 'GIGATON HAMMER': 'GIGATON HMMR',
    'BLAZING TORQUE': 'BLAZE TORQUE', 'NOXIOUS TORQUE': 'NOXIOUS TORQ', 'MAGICAL TORQUE': 'MAGIC TORQUE',
    'TERA STARSTORM': 'TERASTARSTRM', 'BURNING BULWARK': 'BURN BULWARK', 'TACHYON CUTTER': 'TACHYONCUTTR',
    'ALLURING VOICE': 'ALLURE VOICE', 'SUPERCELL SLAM': 'SUPERCELSLAM', 'MALIGNANT CHAIN': 'MALIGN CHAIN',
}

TARGETS = {'TARGET_SELECTED': 'MOVE_TARGET_SELECTED', 'TARGET_USER': 'MOVE_TARGET_USER', 'TARGET_BOTH': 'MOVE_TARGET_BOTH',
           'TARGET_FOES_AND_ALLY': 'MOVE_TARGET_FOES_AND_ALLY', 'TARGET_FIELD': 'MOVE_TARGET_USER',
           'TARGET_ALL_BATTLERS': 'MOVE_TARGET_USER', 'TARGET_ALLY': 'MOVE_TARGET_SELECTED',
           'TARGET_USER_AND_ALLY': 'MOVE_TARGET_USER', 'TARGET_OPPONENTS_FIELD': 'MOVE_TARGET_OPPONENTS_FIELD',
           'TARGET_SMART': 'MOVE_TARGET_SELECTED', 'TARGET_DEPENDS': 'MOVE_TARGET_DEPENDS', 'TARGET_RANDOM': 'MOVE_TARGET_RANDOM'}
CATEGORY = {'DAMAGE_CATEGORY_PHYSICAL': 'MOVE_CATEGORY_PHYSICAL', 'DAMAGE_CATEGORY_SPECIAL': 'MOVE_CATEGORY_SPECIAL',
            'DAMAGE_CATEGORY_STATUS': 'MOVE_CATEGORY_STATUS'}
# move flags the battle code asks about (src/data/move_flags_gen58.h, MP_MOVE_FLAG_*)
EXTRA_FLAGS = ['punchingMove', 'bitingMove', 'soundMove', 'pulseMove', 'ballisticMove', 'slicingMove', 'windMove',
               'danceMove', 'powderMove', 'healingMove', 'ignoresSubstitute', 'thawsUser', 'alwaysCriticalHit',
               'multiHit', 'damagesAirborne', 'ignoresTargetAbility', 'ignoresTargetDefenseEvasionStages',
               'minimizeDoubleDamage', 'gravityBanned', 'metronomeBanned', 'copycatBanned', 'sleepTalkBanned',
               'assistBanned', 'instructBanned', 'mimicBanned', 'meFirstBanned', 'encoreBanned', 'skyBattleBanned',
               'parentalBondBanned', 'dampBanned', 'explosion', 'accuracy50InSun', 'alwaysHitsInRain']

STAT = {'attack': 'ATTACK', 'defense': 'DEFENSE', 'speed': 'SPEED', 'spAtk': 'SPECIAL_ATTACK', 'spDef': 'SPECIAL_DEFENSE',
        'accuracy': 'ACCURACY', 'evasion': 'EVASION'}
STATUS_HIT = {'MOVE_EFFECT_BURN': 'EFFECT_BURN_HIT', 'MOVE_EFFECT_FREEZE': 'EFFECT_FREEZE_HIT',
              'MOVE_EFFECT_FREEZE_OR_FROSTBITE': 'EFFECT_FREEZE_HIT', 'MOVE_EFFECT_PARALYSIS': 'EFFECT_PARALYZE_HIT',
              'MOVE_EFFECT_POISON': 'EFFECT_POISON_HIT', 'MOVE_EFFECT_TOXIC': 'EFFECT_POISON_FANG',
              'MOVE_EFFECT_FLINCH': 'EFFECT_FLINCH_HIT', 'MOVE_EFFECT_CONFUSION': 'EFFECT_CONFUSE_HIT',
              'MOVE_EFFECT_WRAP': 'EFFECT_TRAP', 'MOVE_EFFECT_RECHARGE': 'EFFECT_RECHARGE', 'MOVE_EFFECT_ABSORB': 'EFFECT_ABSORB'}
SAME = {'EFFECT_PROTECT': 'EFFECT_PROTECT', 'EFFECT_FOLLOW_ME': 'EFFECT_FOLLOW_ME', 'EFFECT_RETURN': 'EFFECT_RETURN',
        'EFFECT_FALSE_SWIPE': 'EFFECT_FALSE_SWIPE', 'EFFECT_TRIPLE_KICK': 'EFFECT_TRIPLE_KICK',
        'EFFECT_SOLAR_BEAM': 'EFFECT_SOLAR_BEAM', 'EFFECT_SEMI_INVULNERABLE': 'EFFECT_SHADOW_FORCE',
        'EFFECT_HIT_ESCAPE': 'EFFECT_U_TURN', 'EFFECT_FIXED_PERCENT_DAMAGE': 'EFFECT_SUPER_FANG'}


def stats_of(e):
    return {k: int(v) for k, v in e.items() if k in STAT}


def kai_effect(m):
    """(Kai effect, chance) when Kai has one that does what this move does; None for a new effect."""
    eff, ae = m['effect'], m['additionalEffects']
    flags = m['flags']
    if eff in SAME and not ae:
        return SAME[eff], 0
    if eff == 'EFFECT_RECOIL':
        r = str(m.get('recoil', '33'))
        return {'25': 'EFFECT_RECOIL', '33': 'EFFECT_DOUBLE_EDGE', '50': 'EFFECT_HEAD_SMASH'}.get(r), 100 if r != '25' else 0
    if eff == 'EFFECT_STAT_CHANGE' and len(ae) == 1:
        s, kind = stats_of(ae[0]), ae[0]['moveEffect']
        if kind == 'STAT_CHANGE_EFFECT_PLUS':
            if len(s) == 1:
                (k, v), = s.items()
                return ('EFFECT_%s_UP%s' % (STAT[k], '_2' if v == 2 else ''), 0) if v in (1, 2) else None
            combos = {('attack', 'speed'): 'EFFECT_DRAGON_DANCE', ('spAtk', 'spDef'): 'EFFECT_CALM_MIND',
                      ('attack', 'defense'): 'EFFECT_BULK_UP', ('defense', 'spDef'): 'EFFECT_COSMIC_POWER'}
            if set(s.values()) == {1} and tuple(sorted(s)) in {tuple(sorted(c)) for c in combos}:
                return next(v for c, v in combos.items() if sorted(c) == sorted(s)), 0
        if kind == 'STAT_CHANGE_EFFECT_MINUS' and len(s) == 1:
            (k, v), = s.items()
            if v in (1, 2):
                return 'EFFECT_%s_DOWN%s' % (STAT[k], '_2' if v == 2 else ''), 0
        return None
    if eff != 'EFFECT_HIT':
        return None
    if m.get('strikeCount') == '2' and not ae:
        return 'EFFECT_DOUBLE_HIT', 0
    if 'multiHit' in flags and not ae:
        return 'EFFECT_MULTI_HIT', 0
    if 'alwaysCriticalHit' in flags:
        return None
    if not ae:
        if m.get('criticalHitStage') == '1':
            return 'EFFECT_HIGH_CRITICAL', 0
        return ('EFFECT_QUICK_ATTACK' if m.get('priority', 0) > 0 else 'EFFECT_HIT'), 0
    if len(ae) != 1:
        return None
    e = ae[0]
    chance = int(e.get('chance', '0') or 0)
    self = e.get('self') == 'TRUE'
    k = e['moveEffect']
    if k in STATUS_HIT and not self and not m.get('criticalHitStage'):
        return STATUS_HIT[k], chance
    s = stats_of(e)
    if k == 'MOVE_EFFECT_STAT_MINUS':
        if not self and len(s) == 1:
            (st, v), = s.items()
            if v == 1 and st != 'evasion':
                return 'EFFECT_%s_DOWN_HIT' % STAT[st], chance
            if v == 2 and st == 'spDef':
                return 'EFFECT_SP_DEFENSE_DOWN_2_HIT', chance
        if self:
            if s == {'spAtk': 2}:
                return 'EFFECT_OVERHEAT', 100
            if s == {'attack': 1, 'defense': 1}:
                return 'EFFECT_SUPERPOWER', 100
            if s == {'defense': 1, 'spDef': 1}:
                return 'EFFECT_CLOSE_COMBAT', 100
            if s == {'speed': 1}:
                return 'EFFECT_HAMMER_ARM', 100
    if k == 'MOVE_EFFECT_STAT_PLUS' and self and len(s) == 1:
        (st, v), = s.items()
        if v == 1 and st in ('attack', 'defense', 'spAtk'):
            return {'attack': 'EFFECT_ATTACK_UP_HIT', 'defense': 'EFFECT_DEFENSE_UP_HIT',
                    'spAtk': 'EFFECT_SP_ATTACK_UP_HIT'}[st], chance
    return None


def new_effect_name(m, kai_effects):
    """A new effect's name: expansion's, made from its effect and what it adds, never one of Kai's."""
    eff = m['effect'][len('EFFECT_'):]
    if eff in ('HIT', 'STAT_CHANGE', 'TWO_TURNS_ATTACK', 'EARTHQUAKE', 'PLEDGE', 'RECOIL') or 'EFFECT_' + eff in kai_effects:
        # moves sharing a generic effect: by the move itself (each will need its own script anyway)
        return 'EFFECT_' + m['const'][5:]
    return 'EFFECT_' + eff


def write(rel, text):
    p = os.path.join(REPO, rel)
    old = open(p, encoding='utf-8').read() if os.path.exists(p) else None
    if old != text:
        open(p, 'w', encoding='utf-8').write(text)


def replace_block(rel, start, end, body):
    p = os.path.join(REPO, rel)
    s = open(p, encoding='utf-8').read()
    a = s.index(start)
    b = s.index(end, a) + len(end)
    open(p, 'w', encoding='utf-8').write(s[:a] + start + '\n' + body + end + s[b:])


def kai_name(name):
    n = name.upper().replace('É', 'é')
    if len(n) > 12:
        n = n.replace(' ', '')
    if len(n) > 12:
        n = n.replace("'", '').replace('-', '')
    n = NAMES.get(name.upper(), n)
    if len(n) > 12:
        raise SystemExit('%s: name too long (%s)' % (name, n))
    return n


# the Gen 3 animation a move borrows until it has one of its own: by type, damaging or not
BORROW = {
    'TYPE_NORMAL': ('TAKE_DOWN', 'GROWL'), 'TYPE_FIGHTING': ('KARATE_CHOP', 'BULK_UP'), 'TYPE_FLYING': ('WING_ATTACK', 'FEATHER_DANCE'),
    'TYPE_POISON': ('SLUDGE_BOMB', 'TOXIC'), 'TYPE_GROUND': ('EARTHQUAKE', 'SAND_ATTACK'), 'TYPE_ROCK': ('ROCK_SLIDE', 'ROCK_TOMB'),
    'TYPE_BUG': ('SIGNAL_BEAM', 'SPIDER_WEB'), 'TYPE_GHOST': ('SHADOW_BALL', 'CONFUSE_RAY'), 'TYPE_STEEL': ('IRON_TAIL', 'IRON_DEFENSE'),
    'TYPE_FIRE': ('FLAMETHROWER', 'WILL_O_WISP'), 'TYPE_WATER': ('SURF', 'WATER_SPORT'), 'TYPE_GRASS': ('RAZOR_LEAF', 'INGRAIN'),
    'TYPE_ELECTRIC': ('THUNDERBOLT', 'CHARGE'), 'TYPE_PSYCHIC': ('PSYCHIC', 'CALM_MIND'), 'TYPE_ICE': ('ICE_BEAM', 'HAIL'),
    'TYPE_DRAGON': ('DRAGON_CLAW', 'DRAGON_DANCE'), 'TYPE_DARK': ('CRUNCH', 'TORMENT'), 'TYPE_FAIRY': ('SWEET_KISS', 'MOONLIGHT'),
}


def main():
    moves = json.load(open(os.path.join(HERE, 'moves.json'), encoding='utf-8'))
    kai_effects = set(re.findall(r'#define (EFFECT_\w+)', open(os.path.join(REPO, 'include/constants/battle_move_effects.h')).read()))
    kai_effects -= set(re.findall(r'#define (EFFECT_\w+)', re.search(
        r'// Moemon Kai: Gen 5-8 effects.*?// end of Gen 5-8 effects',
        open(os.path.join(REPO, 'include/constants/battle_move_effects.h')).read(), re.S).group(0)))
    plan, new = {}, []
    for m in moves:
        k = kai_effect(m)
        if k and k[0] in kai_effects:
            plan[m['const']] = k
        else:
            name = new_effect_name(m, kai_effects)
            plan[m['const']] = (name, int((m['additionalEffects'][0].get('chance', '0') if m['additionalEffects'] else '0') or 0))
            if name not in new:
                new.append(name)

    # constants
    body = ''.join('#define %s %d\n' % (m['const'], m['id']) for m in moves)
    body += '#define FIRST_GEN58_MOVE %s\n#define LAST_GEN58_MOVE  %s\n' % (moves[0]['const'], moves[-1]['const'])
    replace_block('include/constants/moves.h', '// Moemon Kai: Gen 5-8 moves (tools/moemon_gen58/gen_moves.py)',
                  '// end of Gen 5-8 moves', body + '\n#define MOVES_COUNT %d\n' % (moves[-1]['id'] + 1))
    body = ''.join('#define %s %d\n' % (e, FIRST_NEW_EFFECT + i) for i, e in enumerate(new))
    replace_block('include/constants/battle_move_effects.h', '// Moemon Kai: Gen 5-8 effects (tools/moemon_gen58/gen_moves.py)',
                  '// end of Gen 5-8 effects', body + '#define NUM_BATTLE_MOVE_EFFECTS %d\n' % (FIRST_NEW_EFFECT + len(new)))

    contest_h = open(os.path.join(REPO, 'include', 'constants', 'contest.h')).read()
    contest_h_wo = re.sub(r'// Moemon Kai: Gen 5-8 combo starters.*?// end of Gen 5-8 combo starters', '', contest_h, flags=re.S)
    kai_contest = set(re.findall(r'#define (CONTEST_\w+|COMBO_STARTER_\w+)', contest_h_wo))
    starters = []
    for m in moves:
        s = m.get('contestComboStarterId', '0')
        if s != '0' and s not in kai_contest and s not in starters:
            starters.append(s)
    last = max(int(v) for v in re.findall(r'#define COMBO_STARTER_\w+\s+(\d+)', contest_h_wo))
    replace_block('include/constants/contest.h', '// Moemon Kai: Gen 5-8 combo starters (tools/moemon_gen58/gen_moves.py)',
                  '// end of Gen 5-8 combo starters', ''.join('#define %s %d\n' % (s, last + 1 + i) for i, s in enumerate(starters)))

    data, names, text, table, contest, cats, mflags = [GEN], [GEN], [GEN], [], [GEN], [GEN], [GEN]
    for m in moves:
        eff, chance = plan[m['const']]
        f = m['flags']
        flags = []
        if 'makesContact' in f:
            flags.append('FLAG_MAKES_CONTACT')
        if 'ignoresProtect' not in f:
            flags.append('FLAG_PROTECT_AFFECTED')
        if 'magicCoatAffected' in f:
            flags.append('FLAG_MAGIC_COAT_AFFECTED')
        if 'snatchAffected' in f:
            flags.append('FLAG_SNATCH_AFFECTED')
        if 'mirrorMoveBanned' not in f:
            flags.append('FLAG_MIRROR_MOVE_AFFECTED')
        if m['power'] and not m['additionalEffects'] and m['category'] != 'DAMAGE_CATEGORY_STATUS':
            flags.append('FLAG_KINGS_ROCK_AFFECTED')
        data.append('    [%s] =\n    {\n        .effect = %s,\n        .power = %d,\n        .type = %s,\n'
                    '        .accuracy = %d,\n        .pp = %d,\n        .secondaryEffectChance = %d,\n'
                    '        .target = %s,\n        .priority = %d,\n        .flags = %s,\n    },\n' % (
                        m['const'], eff, min(m['power'], 255), m['type'], m['accuracy'], m['pp'], chance,
                        TARGETS[m['target']], m['priority'], ' | '.join(flags) or '0'))
        names.append('    [%s] = _("%s"),\n' % (m['const'], kai_name(m['name'])))
        lines = kai_text(m['description']).split('\\n')
        sym = 's%sDescription' % ''.join(w.capitalize() for w in m['const'][5:].split('_'))
        text.append('static const u8 %s[] = _(\n%s);\n\n' % (
            sym, '\n'.join('    "%s%s"' % (l, '\\n' if i < len(lines) - 1 else '') for i, l in enumerate(lines))))
        table.append('    [%s - 1] = %s,' % (m['const'], sym))
        ce = m.get('contestEffect', 'CONTEST_EFFECT_HIGHLY_APPEALING').split(',')[0].strip()
        if ce not in kai_contest:
            ce = 'CONTEST_EFFECT_HIGHLY_APPEALING'
        combos = [x for x in m['contestComboMoves'] if x in kai_contest or x in starters][:4]
        contest.append('    [%s] =\n    {\n        .effect = %s,\n        .contestCategory = %s,\n'
                       '        .comboStarterId = %s,\n        .comboMoves = {%s},\n    },\n' % (
                           m['const'], ce, m.get('contestCategory', 'CONTEST_CATEGORY_COOL').replace('BEAUTIFUL', 'BEAUTY'),
                           m.get('contestComboStarterId', '0'), ', '.join(combos) or '0'))
        cats.append('    [%s] = %s,\n' % (m['const'], CATEGORY[m['category']]))
        fl = [('MP_MOVE_FLAG_' + re.sub(r'([A-Z])', r'_\1', x).upper()) for x in EXTRA_FLAGS if x in f]
        if fl:
            mflags.append('    [%s] = %s,\n' % (m['const'], ' | '.join(fl)))
    write('src/data/battle_moves_gen58.h', ''.join(data))
    write('src/data/text/move_names_gen58.h', ''.join(names))
    write('src/data/text/move_descriptions_gen58.h', ''.join(text) + '#define MOVE_DESCRIPTIONS_GEN58 \\\n' + ' \\\n'.join(table) + '\n')
    write('src/data/contest_moves_gen58.h', ''.join(contest))
    write('src/data/move_categories_gen58.h', ''.join(cats))
    hdr = ['// The flags of Gen 5-8 moves the battle code asks about (MP_MoveFlags, include/battle_gen58.h).\n']
    hdr += ['#define %-46s (1u << %d)\n' % ('MP_MOVE_FLAG_' + re.sub(r'([A-Z])', r'_\1', x).upper(), i) for i, x in enumerate(EXTRA_FLAGS)]
    write('src/data/move_flags_gen58.h', GEN + ''.join(hdr) + 'static const u32 sMoveFlagsGen58[MOVES_COUNT] =\n{\n' + ''.join(mflags[1:]) + '};\n')

    write('data/battle_anim_ptrs_gen58.inc', '@ ' + GEN[3:] + ''.join('\tptrvalue Move_%s\n' % m['const'][5:] for m in moves))
    write('data/battle_effect_ptrs_gen58.inc', '@ ' + GEN[3:] + ''.join(
        '\tptrvalue BattleScript_%s\n' % ''.join(w.capitalize() for w in e.split('_')) for e in new))
    anim_p = os.path.join(REPO, 'data', 'battle_anim_scripts_gen58.inc')
    have = open(anim_p).read() if os.path.exists(anim_p) else (
        '@ Gen 5-8 move animations (Move_<MOVE>). A move without its own borrows a Gen 3 one of its type\n'
        '@ (tools/moemon_gen58/gen_moves.py adds the stubs; tools/moemon_gen4/gen_anims.py ports expansion\'s).\n')
    for m in moves:
        k = m['const'][5:]
        if not re.search(r'^Move_%s:' % k, have, re.M):
            b = BORROW[m['type']][0 if m['category'] != 'DAMAGE_CATEGORY_STATUS' else 1]
            have += '\nMove_%s:\n\tgoto Move_%s\n' % (k, b)
    write('data/battle_anim_scripts_gen58.inc', have)
    eff_p = os.path.join(REPO, 'data', 'battle_scripts_gen58.inc')
    have = open(eff_p).read() if os.path.exists(eff_p) else (
        '@ Moemon Kai (Gen 5-8 fork): battle scripts of the Gen 5-8 move effects (BattleScript_Effect<Name>). Until\n'
        '@ an effect is written, its placeholder plays a plain hit (damaging moves) or fails (status moves).\n')
    status = {plan[m['const']][0] for m in moves if m['category'] == 'DAMAGE_CATEGORY_STATUS'}
    for e in new:
        lab = 'BattleScript_%s' % ''.join(w.capitalize() for w in e.split('_'))
        if not re.search(r'^%s::' % lab, have, re.M):
            have += '\n%s::\n\tgoto %s\n' % (lab, 'BattleScript_EffectSplash' if e in status else 'BattleScript_EffectHit')
    write('data/battle_scripts_gen58.inc', have)
    print('%d moves (%d-%d), %d use Kai effects, %d new effects, %d new combo starters' % (
        len(moves), moves[0]['id'], moves[-1]['id'], sum(1 for m in moves if plan[m['const']][0] not in new), len(new), len(starters)))


if __name__ == '__main__':
    main()
